import{f as e,o,c as t,a2 as i}from"./chunks/framework.BtbFyp-E.js";const m=JSON.parse('{"title":"25 · Prototipo navegable estático (artefacto 4.3)","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/25-prototipo-navegable.md","filePath":"entregables-analisis-diseno/25-prototipo-navegable.md","lastUpdated":null}'),d={name:"entregables-analisis-diseno/25-prototipo-navegable.md"};function r(l,a,s,n,c,p){return o(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="_25-·-prototipo-navegable-estatico-artefacto-4-3" tabindex="-1">25 · Prototipo navegable estático (artefacto 4.3) <a class="header-anchor" href="#_25-·-prototipo-navegable-estatico-artefacto-4-3" aria-label="Permalink to &quot;25 · Prototipo navegable estático (artefacto 4.3)&quot;">​</a></h1><blockquote><p><strong>Prototipo - datos ficticios.</strong> Todo lo que se ve en el prototipo es inventado: cooperativas, personas, documentos, CUIT, importes, correos y números de comprobante. No hay datos reales de ninguna cooperativa ni código de ProCoop.</p></blockquote><table tabindex="0"><thead><tr><th>Campo</th><th>Valor</th></tr></thead><tbody><tr><td>Artefacto</td><td>4.3 · Prototipo navegable (ver <code>00-INDICE.md</code>)</td></tr><tr><td>Carpeta</td><td><code>25-prototipo-navegable/</code></td></tr><tr><td>Base</td><td><code>05-wireframes-pantallas-piloto.md</code> (W-01 a W-17, piloto Internet, olas O0 a O5)</td></tr><tr><td>Rutas y estilo</td><td>T03 §10.9 (rutas canónicas), T03 §7.A (tokens de marca), T03 §10.1/§10.4/§10.5 (AdminShell, AppShell, accesibilidad), M19 (portal del socio)</td></tr><tr><td>Tecnología</td><td>HTML + CSS + JavaScript sin frameworks, sin dependencias externas, sin CDN y sin servidor</td></tr><tr><td>Fecha simulada</td><td>05-11-2026 (fija en todo el prototipo)</td></tr></tbody></table><hr><h2 id="_1-como-abrirlo" tabindex="-1">1. Cómo abrirlo <a class="header-anchor" href="#_1-como-abrirlo" aria-label="Permalink to &quot;1. Cómo abrirlo&quot;">​</a></h2><ol><li>Abrí la carpeta <code>25-prototipo-navegable/</code>.</li><li>Hacé doble clic en <code>index.html</code>. Se abre en el navegador predeterminado (Chrome, Edge o Firefox actuales). No hace falta instalar nada ni tener conexión a Internet.</li><li>La primera pantalla es el <strong>Mapa del prototipo</strong>: tiene los siete recorridos guiados, la tabla de pantallas y accesos directos para entrar como personal, como socio o como técnico.</li></ol><p>Otras indicaciones:</p><ul><li><strong>Estado:</strong> los cambios (altas, cobros, emisiones, OT) se guardan en <code>sessionStorage</code> de la pestaña. Al cerrar la pestaña se pierden.</li><li><strong>Reiniciar datos:</strong> el botón de la barra superior devuelve los datos al estado inicial.</li><li><strong>Navegación:</strong> se usa el fragmento de la URL (<code>index.html#/admin/...</code>). Por eso funciona con <code>file://</code>, y los botones Atrás/Adelante del navegador funcionan.</li><li><strong>Tema:</strong> el admin arranca en tema oscuro. El tema claro se activa desde el Mapa del prototipo o desde el menú de usuario. La PWA (socio y campo) usa siempre la piel oscura <code>.pwa-mod</code>.</li><li><strong>Sin JavaScript:</strong> se muestra un aviso en lugar de las pantallas.</li></ul><h3 id="barra-del-prototipo" tabindex="-1">Barra del prototipo <a class="header-anchor" href="#barra-del-prototipo" aria-label="Permalink to &quot;Barra del prototipo&quot;">​</a></h3><p>Todas las pantallas tienen una barra superior amarilla que no forma parte del producto. Contiene:</p><ul><li>La etiqueta visible <strong>&quot;Prototipo - datos ficticios&quot;</strong>.</li><li>La referencia a la pantalla que se ve: el wireframe (W-xx), la pantalla de la especificación (PAN-xxx) y la ruta canónica.</li><li>El botón <strong>Mapa del prototipo</strong>, que vuelve al inicio.</li><li>El botón <strong>Ficha</strong>, que abre la ficha de la pantalla: propósito, roles, capacidad, ola y ruta.</li><li>El botón <strong>Reiniciar datos</strong>.</li></ul><h2 id="_2-estructura-de-archivos" tabindex="-1">2. Estructura de archivos <a class="header-anchor" href="#_2-estructura-de-archivos" aria-label="Permalink to &quot;2. Estructura de archivos&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>25-prototipo-navegable/</span></span>
<span class="line"><span>├── index.html                      Punto de entrada (doble clic)</span></span>
<span class="line"><span>├── css/</span></span>
<span class="line"><span>│   └── estilos.css                 Tokens (admin claro/oscuro y PWA), shells, componentes, responsive</span></span>
<span class="line"><span>└── js/</span></span>
<span class="line"><span>    ├── datos.js                    Datos ficticios semilla, persistencia en sessionStorage, validación de CUIT</span></span>
<span class="line"><span>    ├── ui.js                       Componentes: insignias de estado, campos, modal, toasts, pestañas, íconos SVG</span></span>
<span class="line"><span>    ├── app.js                      Router por hash, guardas de sesión, AdminShell, AppShell, barra del prototipo, recorridos</span></span>
<span class="line"><span>    ├── pantallas-acceso.js         Mapa del prototipo, login, 2FA, elección de espacio, sin acceso, no encontrada</span></span>
<span class="line"><span>    ├── pantallas-admin-socios.js   Tablero, titulares, alta de persona/titular/cuenta, ficha 360, contrato, servicios</span></span>
<span class="line"><span>    ├── pantallas-admin-operacion.js Lotes, comprobantes, caja, recibos, bandeja, expediente, órdenes de trabajo</span></span>
<span class="line"><span>    ├── pantallas-socio.js          Portal del socio (PWA): inicio, cuentas, facturas, pago, gestiones</span></span>
<span class="line"><span>    └── pantallas-campo.js          App de campo (PWA): Mi día, ejecución de OT, cola sin conexión, stock</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p>Los scripts se cargan como <code>&amp;lt;script&gt;</code> clásicos y en orden (no son módulos ES), para que funcionen al abrir el archivo directamente desde el disco.</p><h2 id="_3-pantallas" tabindex="-1">3. Pantallas <a class="header-anchor" href="#_3-pantallas" aria-label="Permalink to &quot;3. Pantallas&quot;">​</a></h2><p>&quot;—&quot; en la columna Wireframe indica una pantalla de la especificación sin wireframe propio en el documento 05. Se agregó porque los recorridos la necesitan.</p><h3 id="_3-1-acceso" tabindex="-1">3.1 Acceso <a class="header-anchor" href="#_3-1-acceso" aria-label="Permalink to &quot;3.1 Acceso&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Wireframe</th><th>Pantalla</th><th>PAN</th><th>Ruta del prototipo</th></tr></thead><tbody><tr><td>W-01</td><td>Login (usuario y contraseña, SSO simulado)</td><td>PAN-UXD-13 · PAN-POR-23</td><td><code>#/login</code></td></tr><tr><td>W-01</td><td>Verificación en dos pasos</td><td>PAN-UXD-13</td><td><code>#/login/2fa</code></td></tr><tr><td>W-01</td><td>Elegir cooperativa y espacio</td><td>PAN-UXD-13 · PAN-POR-23</td><td><code>#/login/espacio</code></td></tr><tr><td>—</td><td>Sin acceso</td><td>PAN-UXD-12</td><td><code>#/sin-acceso</code></td></tr><tr><td>—</td><td>Página no encontrada</td><td>—</td><td>cualquier ruta inexistente</td></tr></tbody></table><h3 id="_3-2-admin-personal-de-la-cooperativa" tabindex="-1">3.2 Admin (personal de la cooperativa) <a class="header-anchor" href="#_3-2-admin-personal-de-la-cooperativa" aria-label="Permalink to &quot;3.2 Admin (personal de la cooperativa)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Wireframe</th><th>Pantalla</th><th>PAN</th><th>Ruta canónica</th></tr></thead><tbody><tr><td>W-02</td><td>Layout general del admin y buscador (tablero)</td><td>AdminShell · PAN-UXD-04</td><td><code>/admin/inicio</code></td></tr><tr><td>W-02</td><td>Búsqueda de titulares y cuentas</td><td>PAN-PER-01</td><td><code>/admin/per/titulares</code></td></tr><tr><td>—</td><td>Alta de persona, titular y cuenta (modal)</td><td>PAN-PER-04 · PAN-PER-05</td><td>modal lg desde <code>/admin/per/titulares</code> (<code>?alta=1</code>)</td></tr><tr><td>W-03</td><td>Ficha 360 del titular</td><td>PAN-PER-02</td><td><code>/admin/per/titulares/:holderId</code></td></tr><tr><td>W-04</td><td>Alta de contrato de servicio (asistente de 6 pasos)</td><td>PAN-CAT-15</td><td><code>/admin/cat/contracts/new</code></td></tr><tr><td>—</td><td>Catálogo de servicios</td><td>PAN-CAT-03</td><td><code>/admin/cat/services</code></td></tr><tr><td>W-10</td><td>Configuración del servicio Internet</td><td>PAN-CAT-04</td><td><code>/admin/cat/services/:id</code></td></tr><tr><td>—</td><td>Lotes de facturación</td><td>PAN-FAC-05</td><td><code>/admin/fac/lotes</code></td></tr><tr><td>W-06</td><td>Revisión previa del lote (aprobación y emisión)</td><td>PAN-FAC-07</td><td><code>/admin/fac/lotes/:id</code></td></tr><tr><td>W-05</td><td>Listado de comprobantes</td><td>PAN-FAC-09</td><td><code>/admin/fac/comprobantes</code></td></tr><tr><td>—</td><td>Apertura y cierre de caja</td><td>PAN-COB-09</td><td><code>/admin/cob/caja/apertura</code></td></tr><tr><td>W-07</td><td>Cobro en ventanilla</td><td>PAN-COB-10</td><td><code>/admin/cob/caja/cobro</code></td></tr><tr><td>—</td><td>Recibos</td><td>PAN-COB-14</td><td><code>/admin/cob/recibos</code></td></tr><tr><td>W-08</td><td>Bandeja de reclamos y casos</td><td>PAN-CRM-02</td><td><code>/admin/crm/bandeja</code></td></tr><tr><td>W-08</td><td>Expediente del caso</td><td>PAN-CRM-03</td><td><code>/admin/crm/casos/:id</code></td></tr><tr><td>—</td><td>Tablero de órdenes de trabajo</td><td>PAN-TEC-04</td><td><code>/admin/tec/work-orders</code></td></tr><tr><td>W-09</td><td>Ficha de orden de trabajo</td><td>PAN-TEC-05</td><td><code>/admin/tec/work-orders/:id</code></td></tr></tbody></table><p>El AdminShell incluye:</p><ul><li><strong>Barra superior:</strong> marca, contexto de cooperativa y sucursal, buscador global (Ctrl+K), mapa del sitio, accesos fijados, alertas, ayuda de la pantalla (<code>?</code>) y menú de usuario.</li><li><strong>Menú lateral:</strong> agrupado por clústeres, con la opción actual marcada.</li><li><strong>Cabecera de página:</strong> migas de pan y título.</li></ul><p>En tabletas el menú lateral se pliega. Por debajo de 768 px se muestra el aviso de que el admin está pensado para escritorio.</p><p>Si se elige <strong>Cooperativa Ejemplo Dos</strong>, el tablero aparece vacío. Así se ilustra el aislamiento por cooperativa (tenant): cada una ve solo sus datos.</p><h3 id="_3-3-portal-del-socio-pwa-m19" tabindex="-1">3.3 Portal del socio (PWA, M19) <a class="header-anchor" href="#_3-3-portal-del-socio-pwa-m19" aria-label="Permalink to &quot;3.3 Portal del socio (PWA, M19)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Wireframe</th><th>Pantalla</th><th>PAN</th><th>Ruta canónica</th></tr></thead><tbody><tr><td>W-11</td><td>Inicio con saldo</td><td>PAN-POR-25</td><td><code>/app/inicio</code></td></tr><tr><td>—</td><td>Mis cuentas y servicios</td><td>PAN-POR-26</td><td><code>/app/cuentas</code></td></tr><tr><td>W-15</td><td>Vincular cuenta con código</td><td>PAN-POR-27</td><td><code>/app/cuentas/vincular</code></td></tr><tr><td>—</td><td>Mis facturas</td><td>PAN-POR-38</td><td><code>/app/facturas</code></td></tr><tr><td>W-12</td><td>Detalle de factura (&quot;¿Por qué pago esto?&quot;)</td><td>PAN-POR-39</td><td><code>/app/facturas/:invoiceId</code></td></tr><tr><td>W-13</td><td>Pagar (SIRO o cupón de pago en efectivo)</td><td>PAN-POR-40</td><td><code>/app/pagar</code></td></tr><tr><td>W-13</td><td>Resultado del pago</td><td>PAN-POR-41</td><td><code>/app/pagos/:checkoutId</code></td></tr><tr><td>—</td><td>Historial de pagos</td><td>PAN-POR-42</td><td><code>/app/pagos</code></td></tr><tr><td>—</td><td>Mis gestiones</td><td>PAN-POR-50</td><td><code>/app/gestiones</code></td></tr><tr><td>W-14</td><td>Nueva gestión o reclamo (modal)</td><td>PAN-POR-51</td><td><code>/app/gestiones/nueva</code></td></tr><tr><td>—</td><td>Seguimiento de la gestión</td><td>PAN-POR-33</td><td><code>/app/gestiones/:caseId</code></td></tr><tr><td>—</td><td>Contratar un servicio (solo informativa)</td><td>—</td><td><code>/app/contratar</code></td></tr><tr><td>—</td><td>Comunidad (fuera del piloto; estado vacío)</td><td>M17/T09</td><td><code>/app/comunidad</code></td></tr></tbody></table><p>El AppShell del socio tiene:</p><ul><li><strong>Barra superior:</strong> menú, marca de la cooperativa, notificaciones y perfil.</li><li><strong>Barra inferior:</strong> Inicio, Servicios, botón flotante (+), Gestiones y Comunidad.</li></ul><p>En escritorio la app se muestra dentro de un marco de teléfono de 430 px. En el celular ocupa toda la pantalla.</p><h3 id="_3-4-app-de-campo-pwa-tecnicos" tabindex="-1">3.4 App de campo (PWA, técnicos) <a class="header-anchor" href="#_3-4-app-de-campo-pwa-tecnicos" aria-label="Permalink to &quot;3.4 App de campo (PWA, técnicos)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Wireframe</th><th>Pantalla</th><th>PAN</th><th>Ruta canónica</th></tr></thead><tbody><tr><td>W-16</td><td>Mi día: agenda de OT (y vista &quot;Órdenes&quot;)</td><td>PAN-TEC-50</td><td><code>/app/campo/today</code></td></tr><tr><td>W-17</td><td>Ejecución y cierre de OT con evidencias (8 pasos)</td><td>PAN-TEC-51</td><td><code>/app/campo/work-orders/:id</code></td></tr><tr><td>—</td><td>Cola de sincronización</td><td>PAN-TEC-53</td><td><code>/app/campo/sync</code></td></tr><tr><td>—</td><td>Stock en vehículo (solo consulta)</td><td>—</td><td><code>/app/campo/stock</code></td></tr></tbody></table><p>La barra inferior de campo tiene Hoy, Órdenes, botón flotante, Stock y Sincronización.</p><p>Un interruptor del prototipo simula <strong>trabajar sin conexión</strong>:</p><ul><li>Las acciones se encolan con un <code>clientMutationId</code> y se aplican al sincronizar.</li><li>Mientras tanto se muestra un banner de &quot;sin conexión&quot; y el contador de pendientes.</li></ul><h2 id="_4-recorridos-guiados" tabindex="-1">4. Recorridos guiados <a class="header-anchor" href="#_4-recorridos-guiados" aria-label="Permalink to &quot;4. Recorridos guiados&quot;">​</a></h2><p>Cada recorrido se inicia desde el Mapa del prototipo. Al iniciarlo:</p><ul><li>Se restablecen los datos.</li><li>Se inicia la sesión que corresponda.</li><li>Se preparan las precondiciones; por ejemplo, el lote ya emitido para los recorridos 5 y 6.</li></ul><p>Una barra inferior muestra el paso actual con los botones Anterior, Siguiente paso y Salir del recorrido. La barra avanza sola cuando el usuario llega a la pantalla del paso siguiente.</p><table tabindex="0"><thead><tr><th>N.º</th><th>Recorrido</th><th>Pasos principales</th><th>Pantallas</th></tr></thead><tbody><tr><td>1</td><td>Ingreso y selección de cooperativa y espacio</td><td>Ingresar con cualquier usuario y contraseña (p. ej. DNI 00000000). Escribir cualquier código de 6 dígitos y verificar. Elegir la cooperativa y el espacio (probar también &quot;Cooperativa Ejemplo Dos&quot;). Llegar al tablero y usar Ctrl+K.</td><td>W-01, W-02</td></tr><tr><td>2</td><td>Alta de persona, titular y cuenta</td><td>En Titulares, tocar &quot;Nuevo titular&quot;. Completar persona, titular y cuenta. Al guardar se abre la ficha 360 del nuevo titular.</td><td>PAN-PER-01, PAN-PER-04/05, W-03</td></tr><tr><td>3</td><td>Alta de contrato de Internet</td><td>En la ficha 360, la cuenta 0002 no tiene contratos: tocar &quot;Nuevo contrato&quot;. Recorrer los 6 pasos y crear. El contrato queda <strong>Solicitado</strong> y vinculado a un caso de solicitud, que aparece en la bandeja.</td><td>W-03, W-04, W-08</td></tr><tr><td>4</td><td>Facturación: revisión previa y emisión</td><td>Abrir LOT-2026-11-INT (Prefacturado). Revisar la muestra, aprobar (con segregación de funciones) y emitir. El avance del proceso es simulado. Los comprobantes de 11-2026 aparecen en el listado.</td><td>PAN-FAC-05, W-06, W-05</td></tr><tr><td>5</td><td>Cobro en caja y recibo</td><td>Abrir la caja 01 con un fondo inicial. Buscar la cuenta 0001, entregar ARS 40.000 en efectivo (vuelto ARS 5.000) y confirmar con F10. Ver el recibo. La cuenta corriente de la ficha 360 muestra el pago.</td><td>PAN-COB-09, W-07, PAN-COB-14, W-03</td></tr><tr><td>6</td><td>Portal del socio: facturas, pago, vinculación y gestiones</td><td>En Inicio, abrir &quot;Tu última factura&quot; y ver &quot;¿Por qué pago esto?&quot;. Pagar con SIRO; el pago queda pendiente hasta simular la notificación de aprobación (también se puede simular el rechazo). Vincular la cuenta 0002 con el DNI 00000000. Crear una gestión o reclamo con el botón (+) y seguirla.</td><td>W-11, W-12, W-13, PAN-POR-41, W-15, W-14, PAN-POR-33</td></tr><tr><td>7</td><td>Reclamo y orden de trabajo (admin y campo)</td><td>En la bandeja, abrir el reclamo vencido 2026-000040. Tomarlo y crear una OT de reclamo técnico, luego despacharla. Pasar a la app de campo: Mi día, abrir la OT, completar los 8 pasos (checklist, serie, fotos, prueba, conformidad) y marcarla ejecutada. Volver al admin, confirmar y cerrar la OT: el caso queda resuelto.</td><td>W-08, PAN-CRM-03, W-09, W-16, W-17</td></tr></tbody></table><h2 id="_5-datos-ficticios" tabindex="-1">5. Datos ficticios <a class="header-anchor" href="#_5-datos-ficticios" aria-label="Permalink to &quot;5. Datos ficticios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Valores</th></tr></thead><tbody><tr><td>Cooperativas</td><td>&quot;Cooperativa Ejemplo&quot; (Sucursal Centro) y &quot;Cooperativa Ejemplo Dos&quot; (sin datos, para mostrar el aislamiento). CUIT de la cooperativa: 30-00000000-7.</td></tr><tr><td>Personas</td><td>Socio Ejemplo (DNI 00000000, CUIT 20-00000000-1), Ana Prueba, Comercio Ficticio S.R.L. (responsable inscripto), Carlos Muestra. Correos con dominio reservado <code>.example</code>.</td></tr><tr><td>Titulares y cuentas</td><td>Titulares 000123 a 000126. Cuentas 0001 y 0002 (Socio Ejemplo), 0003 (Ana), 0004 (Comercio), 0005 (Carlos).</td></tr><tr><td>Contratos</td><td>INT-0001 Activo desde 28-10-2026. INT-0002 Pendiente de instalación (caso 2026-000045, OT 0000002). INT-0003 e INT-0004 Activos.</td></tr><tr><td>Planes</td><td>Fibra 100: ARS 15.000 por mes y ARS 20.000 de instalación. Fibra 300: ARS 22.000 por mes.</td></tr><tr><td>Facturación</td><td>LOT-2026-10-INT cerrado. LOT-2026-11-INT prefacturado (universo 100, aptos 98, 2 excepciones).</td></tr><tr><td>Atención</td><td>Casos 2026-000039 (resuelto), 2026-000040 (reclamo vencido), 2026-000044 (consulta) y 2026-000045 (solicitud de alta).</td></tr><tr><td>Técnica</td><td>OT 0000001 (cerrada) y 0000002 (asignada a &quot;Cuadrilla Ejemplo 1&quot;, visita 05-11-2026 de 09:00 a 12:00).</td></tr><tr><td>Usuarios demo</td><td>&quot;Usuario Ejemplo D&quot; (personal), &quot;Socio Ejemplo&quot; (socio), &quot;Técnico Ejemplo&quot; (campo).</td></tr></tbody></table><p>Los CUIT se generan con un dígito verificador válido. El alta de persona valida:</p><ul><li>el formato y el dígito verificador del CUIT</li><li>que el CUIT coincida con el DNI</li><li>que no haya un documento duplicado</li></ul><h2 id="_6-diseno-y-accesibilidad" tabindex="-1">6. Diseño y accesibilidad <a class="header-anchor" href="#_6-diseno-y-accesibilidad" aria-label="Permalink to &quot;6. Diseño y accesibilidad&quot;">​</a></h2><h3 id="tokens-y-piel-visual" tabindex="-1">Tokens y piel visual <a class="header-anchor" href="#tokens-y-piel-visual" aria-label="Permalink to &quot;Tokens y piel visual&quot;">​</a></h3><ul><li>Se usan los tokens de T03 §7.A: piel admin en tema oscuro y claro, piel PWA <code>.pwa-mod</code> con fondo negro y halo lila, radios, espaciado, alturas y escala de z-index.</li><li>Tres valores se ajustaron solo en el prototipo para cumplir el contraste que T03 declara. Ver la sección 9, Observaciones.</li></ul><h3 id="tipografia" tabindex="-1">Tipografía <a class="header-anchor" href="#tipografia" aria-label="Permalink to &quot;Tipografía&quot;">​</a></h3><ul><li>No se descarga ninguna fuente.</li><li>Space Grotesk, IBM Plex Sans/Mono y Sora se usan solo si están instaladas en el equipo. Si no, se usa la fuente del sistema (Segoe UI, system-ui, Roboto).</li></ul><h3 id="insignias-de-estado-statusbadge" tabindex="-1">Insignias de estado (StatusBadge) <a class="header-anchor" href="#insignias-de-estado-statusbadge" aria-label="Permalink to &quot;Insignias de estado (StatusBadge)&quot;">​</a></h3><ul><li>Siempre muestran ícono y texto; el estado nunca se comunica solo con color.</li><li>Los mapas de estado siguen las máquinas de estados de la especificación: contrato, estado comercial y fiscal del comprobante, lote, caso, OT, checkout y caja.</li></ul><h3 id="accesibilidad" tabindex="-1">Accesibilidad <a class="header-anchor" href="#accesibilidad" aria-label="Permalink to &quot;Accesibilidad&quot;">​</a></h3><ul><li><strong>Navegación y foco:</strong><ul><li>Enlace &quot;Saltar al contenido&quot;.</li><li>Foco visible en todos los controles.</li><li>Al navegar, el foco va al <code>h1</code> de la pantalla, y se conserva al volver a dibujar la misma pantalla.</li></ul></li><li><strong>Formularios:</strong><ul><li>Etiquetas asociadas a cada campo y marca de obligatorio en texto.</li><li>Errores en línea con <code>aria-describedby</code> y un resumen de errores que recibe el foco.</li><li><code>autocomplete</code> donde corresponde, incluido <code>one-time-code</code> en la verificación.</li></ul></li><li><strong>Componentes:</strong><ul><li>Modales nativos <code>&amp;lt;dialog&gt;</code> con título asociado y cierre con Esc.</li><li>Pestañas con <code>role=&quot;tablist&quot;</code> y navegación con flechas.</li><li>Tablas con <code>th scope</code>.</li><li>Regiones <code>aria-live</code> para avisos y toasts. Los toasts de error no se cierran solos.</li></ul></li><li><strong>Tamaño y movimiento:</strong><ul><li>Objetivos táctiles de 44 px o más en la PWA.</li><li>Se respeta <code>prefers-reduced-motion</code>.</li></ul></li></ul><h3 id="diseno-adaptable" tabindex="-1">Diseño adaptable <a class="header-anchor" href="#diseno-adaptable" aria-label="Permalink to &quot;Diseño adaptable&quot;">​</a></h3><ul><li><strong>Admin:</strong><ul><li>El menú lateral se pliega por debajo de 1024 px.</li><li>Las grillas pasan a una columna por debajo de 768 px, donde también aparece el aviso de uso en escritorio.</li></ul></li><li><strong>PWA:</strong> marco de teléfono en escritorio y pantalla completa en el celular.</li></ul><h2 id="_7-alcance" tabindex="-1">7. Alcance <a class="header-anchor" href="#_7-alcance" aria-label="Permalink to &quot;7. Alcance&quot;">​</a></h2><p>El prototipo cubre:</p><ul><li>Los 17 wireframes (W-01 a W-17).</li><li>Las pantallas auxiliares que los recorridos necesitan: PAN-PER-04/05, PAN-CAT-03, PAN-FAC-05, PAN-COB-09, PAN-COB-14, PAN-TEC-04, PAN-TEC-53 y las listas del portal.</li><li>Los siete recorridos pedidos.</li></ul><p>Las reglas visibles en los wireframes están simuladas en el navegador:</p><ul><li><strong>Estados:</strong><ul><li>Las transiciones de contrato, lote, caso y OT siguen las máquinas de estados de la especificación.</li><li>El contrato nuevo nace Solicitado.</li><li>La facturación empieza con la activación.</li></ul></li><li><strong>Permisos y controles:</strong><ul><li>Segregación de funciones en la aprobación del lote.</li><li>Confirmación con escritura del identificador para anular.</li></ul></li><li><strong>Caja:</strong><ul><li>Sesión de caja obligatoria para cobrar.</li><li>Vuelto, pago parcial y varios medios de pago.</li></ul></li><li><strong>Portal y campo:</strong><ul><li>Antienumeración y límite de intentos en la vinculación.</li><li>Protección contra doble envío en el pago.</li><li>Requisitos de cierre de la OT.</li><li>Cola sin conexión.</li></ul></li></ul><h2 id="_8-limitaciones" tabindex="-1">8. Limitaciones <a class="header-anchor" href="#_8-limitaciones" aria-label="Permalink to &quot;8. Limitaciones&quot;">​</a></h2><ul><li><strong>Sin servidor:</strong><ul><li>No hay persistencia real ni concurrencia.</li><li>La seguridad, los permisos y el aislamiento por cooperativa están simulados en la interfaz.</li><li>El usuario demo del admin tiene todos los roles.</li></ul></li><li><strong>Integraciones simuladas:</strong><ul><li>SSO, verificación en dos pasos, pasarela SIRO y notificación de pago.</li><li>Autorización fiscal (CAE).</li><li>Impresión de recibos (agente local).</li><li>Generación de PDF.</li><li>Mapas y georreferencia.</li><li>Carga de archivos y fotos.</li><li>Lectura de código de barras y de número de serie.</li><li>Dictado.</li><li>Instalación de la PWA y notificaciones push.</li></ul></li><li><strong>Detalle parcial:</strong><ul><li>No todas las pestañas o secciones de las pantallas tienen el detalle completo. Las que no lo tienen muestran un estado vacío explicativo.</li><li>En la vinculación de cuenta solo se implementa el primer método, número de cuenta y documento.</li></ul></li><li><strong>No implementado:</strong><ul><li>Confirmación de &quot;cambios sin guardar&quot; al salir de un formulario.</li><li>Búsqueda difusa ni paginación real.</li><li>Internacionalización, más allá del español rioplatense.</li></ul></li><li><strong>Diferencias con la especificación:</strong><ul><li>El asistente de contrato W-04 está especificado como modal, pero tiene ruta propia. En el prototipo se implementó como página, por la ruta.</li><li>El selector de cooperativa del admin no tiene ruta canónica (AD-01). Se usa <code>#/login/espacio</code>.</li></ul></li><li><strong>Navegadores:</strong> probado en navegadores Chromium actuales. Requiere soporte de <code>&amp;lt;dialog&gt;</code> y de <code>:has()</code> (solo estético).</li></ul><h2 id="_9-observaciones" tabindex="-1">9. Observaciones <a class="header-anchor" href="#_9-observaciones" aria-label="Permalink to &quot;9. Observaciones&quot;">​</a></h2><p>Inconsistencias o vacíos detectados en la especificación durante la construcción. <strong>No se corrigió la especificación.</strong> Cuando hubo que elegir, en el prototipo se siguió la regla de negocio y no el texto del wireframe.</p><ol><li><strong>W-04: estado resultante del contrato.</strong> El resumen del asistente muestra &quot;Estado resultante: Pendiente de instalación&quot;. El mismo wireframe dice que el contrato se crea Solicitado, e Internet requiere factibilidad (DEC-040, RN-CAT-026). El prototipo crea el contrato en <strong>Solicitado</strong>.</li><li><strong>W-03 / W-12: cobro de la instalación.</strong> Los wireframes facturan la instalación y el abono de INT-0001 mientras W-03 lo muestra Pendiente de instalación. Esto contradice M02 T06: la facturación empieza con la activación. En el prototipo, INT-0001 está <strong>Activo desde el 28-10-2026</strong>, y la factura 11-2026 (ARS 15.000 + 20.000 = 35.000) es coherente con esa activación.</li><li><strong>Número de caso 2026-000045 duplicado.</strong> Se usa como la solicitud de alta de Internet (W-11, W-03, W-09) y como el reclamo &quot;Lentitud intermitente&quot; (W-08). El prototipo lo usa solo para la solicitud de alta; el reclamo de la bandeja es 2026-000040.</li><li><strong>CUIT de ejemplo inválido.</strong> El CUIT 20-00000000-0 de los ejemplos no pasa la validación de dígito verificador; el válido es 20-00000000-1. El prototipo usa CUIT calculados con dígito verificador correcto.</li><li><strong>Contraste de tokens de T03 §7.A.</strong> Algunos valores declarados no alcanzan la relación de contraste que T03 promete: <ul><li><code>--line-strong</code> oscuro <code>#3b3450</code> sobre <code>--panel</code> da alrededor de 1,45:1, y el claro <code>#c3bdd3</code> alrededor de 1,8:1. T03 declara 3:1 o más para bordes de controles. El prototipo usa <code>#7a7192</code> (oscuro) y <code>#8a84a0</code> (claro).</li><li><code>--ok</code> claro <code>#1f8f5f</code> como texto da alrededor de 4,07:1, frente al 4,5:1 declarado. El prototipo usa <code>#1a7a51</code>.</li><li>El borde de campos de la PWA con blanco al 32 % sobre <code>#17171d</code> queda por debajo de 3:1. El prototipo usa blanco al 40 %.</li><li>Para enlaces sobre el panel se definió <code>--brand-accessible</code>: <code>#aea4fa</code> en el tema oscuro y <code>#5a49e0</code> en el claro.</li></ul></li><li><strong>Rutas y capacidades distintas entre T03 §10.8.2 y §10.9.4:</strong><ul><li>SM-PWS-010: <code>/pagar/resultado/:id</code> con <code>por.pagos.ver</code> frente a <code>/app/pagos/:checkoutId</code> con <code>por.pagos.crear</code>. El prototipo usa <code>/app/pagos/:checkoutId</code>.</li><li>SM-PWS-001: <code>por.inicio.ver</code> frente a <code>por.portal.ver</code>.</li><li>SM-PWS-017: <code>por.gestiones.ver</code> frente a <code>por.gestiones.crear</code> (ya registrado como AD-13).</li></ul></li><li><strong>W-07: número de comprobante abreviado.</strong> Se usa &quot;FC B 0001-01&quot;. El prototipo muestra el número completo (punto de venta de 4 dígitos y número de 8).</li><li><strong>Pantallas sin wireframe.</strong> El alta de persona, titular y cuenta (PAN-PER-04/05) y la apertura de caja (PAN-COB-09) no tienen wireframe propio en el documento 05, aunque los recorridos pedidos las necesitan. Se diseñaron siguiendo los patrones de T03.</li><li><strong>Selector de cooperativa del admin sin ruta.</strong> No hay ruta canónica para el selector de cooperativa y espacio del personal (pendiente AD-01). El prototipo lo resuelve con <code>#/login/espacio</code>.</li><li><strong>W-04: modal o página.</strong> El asistente se especifica como modal pero tiene ruta propia (<code>/admin/cat/contracts/new</code>). El prototipo lo implementa como página para respetar la ruta.</li><li><strong>Números de cuenta de ejemplo en el portal.</strong> Los textos de ejemplo del portal usan &quot;Cta 0007&quot; y otros números que no coinciden con las cuentas de los wireframes del admin. El prototipo usa el mismo conjunto de cuentas (0001 a 0005) en todos los espacios.</li></ol>`,64)])])}const g=e(d,[["render",r]]);export{m as __pageData,g as default};
